//! The compressed icon bundle generated by `icons/sets/generate.py`.
use {
    super::IconShortcode,
    anyhow::{Context, Result, bail, ensure},
    flate2::read::DeflateDecoder,
    std::io::Read,
};

/// Artwork for one icon: its `viewBox` and `<path>` elements.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct IconArtwork {
    pub(crate) view_box: String,
    pub(crate) paths:    String,
}

/// The read-only icon sets compiled into GraphArch.
pub(crate) struct IconBundle(&'static [u8]);
impl IconBundle {
    const MAGIC: &'static [u8] = b"GAICONS1\n";
    /// The largest decompressed shard GraphArch reads.
    const SHARD_LIMIT: u64 = 4 * 1024 * 1024;

    pub(crate) const fn builtin() -> Self {
        Self(include_bytes!(
            "../render/website/project/icons/sets/icons.bin"
        ))
    }

    /// Look up an icon; `None` when no bundled set holds it.
    pub(crate) fn artwork(
        &self,
        shortcode: &IconShortcode,
    ) -> Result<Option<IconArtwork>> {
        let Some(shard) = self.shard(shortcode.shard())? else {
            return Ok(None)
        };
        let mut text = String::new();
        DeflateDecoder::new(shard)
            .take(Self::SHARD_LIMIT)
            .read_to_string(&mut text)
            .context("bundled icon shard is not valid deflate UTF-8")?;
        for line in text.lines() {
            let mut fields = line.splitn(3, '\t');
            let (Some(name), Some(view_box), Some(paths)) =
                (fields.next(), fields.next(), fields.next())
            else {
                bail!("malformed bundled icon line")
            };
            if name == shortcode.as_str() {
                ensure!(
                    paths.starts_with("<path ") &&
                        paths.split("<path ").skip(1).all(|path| {
                            path.ends_with("/>") && !path.contains('<')
                        }),
                    "bundled icon {name} holds more than path geometry"
                );
                return Ok(Some(IconArtwork {
                    view_box: view_box.into(),
                    paths:    paths.into(),
                }));
            }
        }
        Ok(None)
    }

    fn shard(&self, key: &str) -> Result<Option<&'static [u8]>> {
        let rest = self
            .0
            .strip_prefix(Self::MAGIC)
            .context("bundled icons lack their header")?;
        let end = rest
            .windows(2)
            .position(|window| window == b"\n\n")
            .context("bundled icon index is unterminated")?;
        let index = std::str::from_utf8(&rest[..end])?;
        let data = &rest[end + 2..];
        for line in index.lines() {
            let mut fields = line.split('\t');
            let (Some(shard), Some(offset), Some(length)) =
                (fields.next(), fields.next(), fields.next())
            else {
                bail!("malformed bundled icon index")
            };
            if shard == key {
                let offset: usize = offset.parse()?;
                let length: usize = length.parse()?;
                return data
                    .get(offset..offset + length)
                    .map(Some)
                    .context("bundled icon shard is out of range");
            }
        }
        Ok(None)
    }
}
